package com.crms.controller;import com.crms.entity.*;import com.crms.enums.*;import com.crms.repository.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/jobs") public class JobController{private final JobRepository jobs;private final CompanyRepository companies;private final UserRepository users;public JobController(JobRepository j,CompanyRepository c,UserRepository u){jobs=j;companies=c;users=u;}@GetMapping public List<Map<String,Object>> list(@RequestParam(required=false)JobStatus status,@RequestParam(required=false)Boolean mine,Authentication a){List<JobPosting> rows=Boolean.TRUE.equals(mine)&&a!=null?jobs.findByCompanyOwnerId(users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId()):(status==null?jobs.findAll():jobs.findByStatus(status));return rows.stream().map(this::view).toList();}@GetMapping("/{id}")public Map<String,Object> get(@PathVariable Long id){return view(jobs.findById(id).orElseThrow());}@PostMapping public ResponseEntity<?> create(@Valid @RequestBody JobPosting input,Authentication a){var c=companies.findByOwnerId(users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId()).orElseThrow();input.setCompany(c);return ResponseEntity.status(201).body(view(jobs.save(input)));}@PutMapping("/{id}")public Map<String,Object> update(@PathVariable Long id,@RequestBody JobPosting in,Authentication a){var j=jobs.findById(id).orElseThrow();assertOwner(j,a);j.setTitle(in.getTitle());j.setDescription(in.getDescription());j.setLocation(in.getLocation());j.setMinCgpa(in.getMinCgpa());j.setGraduationYear(in.getGraduationYear());j.setMaxBacklogs(in.getMaxBacklogs());j.setStatus(in.getStatus());return view(jobs.save(j));}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id,Authentication a){assertOwner(jobs.findById(id).orElseThrow(),a);jobs.deleteById(id);}private void assertOwner(JobPosting j,Authentication a){var u=users.findByEmailIgnoreCase(a.getName()).orElseThrow();if(!j.getCompany().getOwner().getId().equals(u.getId())&&u.getRole()!=Role.ADMIN&&u.getRole()!=Role.PLACEMENT_OFFICER)throw new org.springframework.security.access.AccessDeniedException("Not authorized");}private Map<String,Object> view(JobPosting j){return Map.of("id",j.getId(),"title",j.getTitle(),"description",Objects.toString(j.getDescription(),""),"location",Objects.toString(j.getLocation(),""),"jobType",Objects.toString(j.getJobType(),""),"minCgpa",Objects.toString(j.getMinCgpa(),""),"graduationYear",Objects.toString(j.getGraduationYear(),""),"status",j.getStatus().name(),"companyName",j.getCompany().getName());}}
